{"cmd":"cd /mnt/data2/dev/develop/semantic-search-engine && cat > check-dev.sh <<'EOF'
#!/bin/bash
#
# Local quality gate: formatting + static analysis + type check + security.
#
#   ./check-dev.sh            # everything
#   ./check-dev.sh format     # black (in-place)
#   ./check-dev.sh lint       # flake8 + bandit
#   ./check-dev.sh types      # mypy
#   ./check-dev.sh test       # pytest (server + client)
#
set -euo pipefail
cd "$(dirname -- "${BASH_SOURCE[0]:-$0}")"

MODE="${1:-all}"

run_format() {
  black .
}

run_lint() {
  flake8 .
  bandit -r src/ scripts/ -c pyproject.toml -q
}

run_types() {
  mypy src/sse_api src/sse_lib
}

run_test() {
  python3 -m pytest
}

case "$MODE" in
  format) run_format ;;
  lint)   run_lint ;;
  types)  run_types ;;
  test)   run_test ;;
  all)    run_format; run_lint; run_types; run_test ;;
  *) echo "usage: $0 [all|format|lint|types|test]"; exit 1 ;;
esac
EOF
chmod +x check-dev.sh
# bandit -c needs a setup.cfg/pyproject; bandit reads [tool.bandit]? No, bandit uses .bandit or -c INI.
# Provide a minimal bandit ini so `bandit -c` is not needed; bandit reads pyproject only for skips? Actually bandit supports `--profile`/`-c` ini.
# Keep it simple: pass -c .bandit.ini. Create it.
cat > .bandit <<'EOF'
[bandit]
skips = B101,B110,B112
EOF
python3 - <<'EOF'
p = "check-dev.sh"
s = open(p).read()
s = s.replace("  bandit -r src/ scripts/ -c pyproject.toml -q",
              "  bandit -r src/ scripts/ -c .bandit -q")
open(p, "w").write(s)
EOF
echo "done""}

